
INSERT INTO public.risk_explanation_translations (hazard_zone_id, language_code, explanation_text)
SELECT z.id, v.lang, v.txt FROM public.hazard_zones z
JOIN (VALUES
('Guwahati','en','High flood risk from proximity to the Brahmaputra flood plain. Seasonal inundation recurs during the June to September monsoon, worsened by hillside runoff and drainage congestion.'),
('Guwahati','hi','ब्रह्मपुत्र के बाढ़ क्षेत्र के निकट होने के कारण इस क्षेत्र में बाढ़ का उच्च जोखिम है। जून से सितंबर तक मानसून में हर वर्ष जलभराव होता है, जिसे पहाड़ी बहाव और जल निकासी की रुकावट और बढ़ा देती है।'),
('Guwahati','bn','ব্রহ্মপুত্রের প্লাবনভূমির কাছাকাছি হওয়ায় এই এলাকায় বন্যার ঝুঁকি বেশি। জুন থেকে সেপ্টেম্বর পর্যন্ত বর্ষায় নিয়মিত জলমগ্নতা হয়, পাহাড়ি ঢল ও নিকাশি সমস্যায় তা আরও বাড়ে।'),
('Guwahati','gu','બ્રહ્મપુત્રના પૂરમેદાનની નજીક હોવાથી આ વિસ્તારમાં પૂરનું ઊંચું જોખમ છે. જૂનથી સપ્ટેમ્બર સુધીના ચોમાસામાં દર વર્ષે પાણી ભરાય છે, ટેકરીઓનું વહેણ અને ગટર જામ થવાથી સ્થિતિ વધુ ખરાબ થાય છે.'),
('Guwahati','kn','ಬ್ರಹ್ಮಪುತ್ರ ಪ್ರವಾಹ ಬಯಲಿಗೆ ಸಮೀಪವಿರುವುದರಿಂದ ಈ ಪ್ರದೇಶದಲ್ಲಿ ಪ್ರವಾಹದ ಅಪಾಯ ಹೆಚ್ಚು. ಜೂನ್‌ನಿಂದ ಸೆಪ್ಟೆಂಬರ್‌ವರೆಗಿನ ಮಳೆಗಾಲದಲ್ಲಿ ಪ್ರತಿ ವರ್ಷ ನೀರು ನಿಲ್ಲುತ್ತದೆ; ಬೆಟ್ಟದ ಹರಿವು ಮತ್ತು ಚರಂಡಿ ತಡೆ ಇದನ್ನು ಇನ್ನಷ್ಟು ಹದಗೆಡಿಸುತ್ತದೆ.'),
('Guwahati','ml','ബ്രഹ്മപുത്ര വെള്ളപ്പൊക്ക സമതലത്തിനോട് ചേർന്നു കിടക്കുന്നതിനാൽ ഈ പ്രദേശത്ത് വെള്ളപ്പൊക്ക സാധ്യത കൂടുതലാണ്. ജൂൺ മുതൽ സെപ്റ്റംബർ വരെയുള്ള മൺസൂണിൽ എല്ലാ വർഷവും വെള്ളക്കെട്ട് ഉണ്ടാകുന്നു; മലയോര ഒഴുക്കും ഓട തടസ്സവും ഇത് വർധിപ്പിക്കുന്നു.'),
('Guwahati','mr','ब्रह्मपुत्रेच्या पूरक्षेत्राजवळ असल्याने या भागात पुराचा मोठा धोका आहे. जून ते सप्टेंबर या पावसाळ्यात दरवर्षी पाणी साचते; डोंगरउतारावरील प्रवाह आणि तुंबलेली गटारे यामुळे स्थिती अधिक बिकट होते.'),
('Guwahati','pa','ਬ੍ਰਹਮਪੁੱਤਰ ਦੇ ਹੜ੍ਹ ਮੈਦਾਨ ਦੇ ਨੇੜੇ ਹੋਣ ਕਾਰਨ ਇਸ ਇਲਾਕੇ ਵਿੱਚ ਹੜ੍ਹ ਦਾ ਵੱਡਾ ਖ਼ਤਰਾ ਹੈ। ਜੂਨ ਤੋਂ ਸਤੰਬਰ ਤੱਕ ਮਾਨਸੂਨ ਵਿੱਚ ਹਰ ਸਾਲ ਪਾਣੀ ਭਰ ਜਾਂਦਾ ਹੈ, ਪਹਾੜੀ ਵਹਾਅ ਅਤੇ ਨਿਕਾਸੀ ਬੰਦ ਹੋਣ ਨਾਲ ਹਾਲਾਤ ਹੋਰ ਵਿਗੜਦੇ ਹਨ।'),
('Guwahati','ta','பிரம்மபுத்திரா வெள்ளச் சமவெளிக்கு அருகில் இருப்பதால் இப்பகுதியில் வெள்ள அபாயம் அதிகம். ஜூன் முதல் செப்டம்பர் வரையிலான பருவமழையில் ஒவ்வொரு ஆண்டும் நீர் தேங்குகிறது; மலைச்சரிவு நீரோட்டமும் வடிகால் அடைப்பும் இதை மேலும் மோசமாக்குகின்றன.'),
('Guwahati','te','బ్రహ్మపుత్ర వరద మైదానానికి సమీపంలో ఉన్నందున ఈ ప్రాంతంలో వరద ముప్పు ఎక్కువ. జూన్ నుంచి సెప్టెంబర్ వరకు రుతుపవనాల్లో ప్రతి ఏటా నీరు నిలుస్తుంది; కొండ ప్రవాహాలు, మురుగు కాలువల అడ్డంకులు దీన్ని మరింత తీవ్రతరం చేస్తాయి.'),
('Guwahati','or','ବ୍ରହ୍ମପୁତ୍ର ପ୍ଲାବନଭୂମି ନିକଟରେ ଥିବାରୁ ଏହି ଅଞ୍ଚଳରେ ବନ୍ୟାର ଉଚ୍ଚ ବିପଦ ରହିଛି। ଜୁନରୁ ସେପ୍ଟେମ୍ବର ମୌସୁମୀରେ ପ୍ରତିବର୍ଷ ଜଳ ଜମେ; ପାହାଡ଼ି ଜଳସ୍ରୋତ ଓ ନାଳ ଅବରୋଧ ଏହାକୁ ଆହୁରି ଗମ୍ଭୀର କରେ।'),
('Guwahati','ur','دریائے برہم پترا کے سیلابی میدان کے قریب ہونے کے باعث اس علاقے میں سیلاب کا شدید خطرہ ہے۔ جون تا ستمبر مون سون میں ہر سال پانی جمع ہوتا ہے، پہاڑی بہاؤ اور نکاسی کی رکاوٹ صورتحال کو مزید خراب کرتی ہے۔'),
('Mumbai','en','Kurla lies in a low-lying Mithi river basin with heavily strained storm-water drainage. Severe monsoon flooding is documented, including 2005, and waterlogging recurs when high tide coincides with heavy rain.'),
('Mumbai','hi','कुर्ला मीठी नदी के निचले बेसिन में स्थित है जहाँ वर्षा-जल निकासी पर भारी दबाव है। 2005 सहित भीषण मानसून बाढ़ का दस्तावेज़ी इतिहास है, और तेज़ बारिश के साथ उच्च ज्वार आने पर जलभराव दोहराता है।'),
('Mumbai','bn','কুরলা মিঠি নদীর নিচু অববাহিকায় অবস্থিত, যেখানে বৃষ্টির জল নিকাশি ব্যবস্থা মারাত্মক চাপে থাকে। ২০০৫ সালসহ ভয়াবহ বর্ষা বন্যার নথিভুক্ত ইতিহাস রয়েছে এবং ভরা জোয়ারের সঙ্গে ভারী বৃষ্টি মিললে জলাবদ্ধতা ফিরে আসে।'),
('Mumbai','gu','કુર્લા મીઠી નદીના નીચાણવાળા થાળામાં આવેલું છે જ્યાં વરસાદી પાણીની ગટર વ્યવસ્થા પર ભારે દબાણ છે. 2005 સહિત ભારે ચોમાસુ પૂરનો ઇતિહાસ નોંધાયેલો છે, અને ભરતી સાથે ભારે વરસાદ થતાં પાણી ભરાય છે.'),
('Mumbai','kn','ಕುರ್ಲಾ ಮಿಠಿ ನದಿಯ ತಗ್ಗು ಪ್ರದೇಶದಲ್ಲಿದ್ದು, ಮಳೆನೀರು ಚರಂಡಿ ವ್ಯವಸ್ಥೆ ತೀವ್ರ ಒತ್ತಡದಲ್ಲಿದೆ. 2005ರ ಸೇರಿದಂತೆ ತೀವ್ರ ಮಳೆಗಾಲದ ಪ್ರವಾಹಗಳ ದಾಖಲೆ ಇದೆ; ಭರತ ಮತ್ತು ಭಾರೀ ಮಳೆ ಒಟ್ಟಿಗೆ ಬಂದಾಗ ನೀರು ನಿಲ್ಲುತ್ತದೆ.'),
('Mumbai','ml','കുർള മീഠി നദിയുടെ താഴ്ന്ന തടത്തിലാണ്; മഴവെള്ള നിർഗമന സംവിധാനം കടുത്ത സമ്മർദ്ദത്തിലാണ്. 2005 ഉൾപ്പെടെ കടുത്ത മൺസൂൺ വെള്ളപ്പൊക്കങ്ങൾ രേഖപ്പെടുത്തിയിട്ടുണ്ട്; വേലിയേറ്റവും കനത്ത മഴയും ഒന്നിക്കുമ്പോൾ വെള്ളക്കെട്ട് ആവർത്തിക്കുന്നു.'),
('Mumbai','mr','कुर्ला मिठी नदीच्या सखल खोऱ्यात असून पावसाळी पाणी निचरा यंत्रणेवर प्रचंड ताण आहे. 2005 सह तीव्र पावसाळी पुराचा नोंदलेला इतिहास आहे आणि भरतीसोबत जोरदार पाऊस आल्यास पाणी साचते.'),
('Mumbai','pa','ਕੁਰਲਾ ਮੀਠੀ ਨਦੀ ਦੇ ਨੀਵੇਂ ਬੇਸਿਨ ਵਿੱਚ ਹੈ ਜਿੱਥੇ ਮੀਂਹ ਦੇ ਪਾਣੀ ਦੀ ਨਿਕਾਸੀ ਉੱਤੇ ਭਾਰੀ ਦਬਾਅ ਹੈ। 2005 ਸਮੇਤ ਭਿਆਨਕ ਮਾਨਸੂਨੀ ਹੜ੍ਹਾਂ ਦਾ ਰਿਕਾਰਡ ਹੈ, ਅਤੇ ਤੇਜ਼ ਮੀਂਹ ਨਾਲ ਜਵਾਰ ਮਿਲਣ ਤੇ ਪਾਣੀ ਭਰ ਜਾਂਦਾ ਹੈ।'),
('Mumbai','ta','கூர்லா மிதி ஆற்றின் தாழ்வான படுகையில் அமைந்துள்ளது; மழைநீர் வடிகால் அமைப்பு கடும் அழுத்தத்தில் உள்ளது. 2005 உட்பட கடும் பருவமழை வெள்ளங்கள் பதிவாகியுள்ளன; உயர் அலையுடன் கனமழை சேரும்போது நீர் தேக்கம் மீண்டும் ஏற்படுகிறது.'),
('Mumbai','te','కుర్లా మిఠీ నదీ లోతట్టు పరీవాహకంలో ఉంది; వర్షపు నీటి కాలువ వ్యవస్థపై తీవ్ర ఒత్తిడి ఉంది. 2005తో సహా తీవ్ర రుతుపవన వరదల చరిత్ర నమోదైంది; పోటుతో పాటు భారీ వర్షం కురిస్తే నీరు నిలుస్తుంది.'),
('Mumbai','or','କୁର୍ଲା ମିଠି ନଦୀର ନିମ୍ନ ଅବବାହିକାରେ ଅବସ୍ଥିତ, ଯେଉଁଠି ବର୍ଷାଜଳ ନିଷ୍କାସନ ବ୍ୟବସ୍ଥା ଉପରେ ଅତ୍ୟଧିକ ଚାପ ରହିଛି। 2005 ସହିତ ଭୟଙ୍କର ମୌସୁମୀ ବନ୍ୟାର ନଥି ରହିଛି ଏବଂ ପୂର୍ଣ୍ଣ ଜୁଆର ସହ ପ୍ରବଳ ବର୍ଷା ହେଲେ ଜଳ ଜମେ।'),
('Mumbai','ur','کرلا میٹھی ندی کے نشیبی طاس میں واقع ہے جہاں برساتی پانی کی نکاسی شدید دباؤ کا شکار ہے۔ 2005 سمیت شدید مون سون سیلابوں کا ریکارڈ موجود ہے، اور تیز بارش کے ساتھ مدوجزر ملنے پر پانی جمع ہو جاتا ہے۔'),
('Kochi','en','Moderate flood exposure from coastal storm surge and backwater overflow across the Vembanad system. Tidal ingress combined with monsoon rainfall causes waterlogging in low-lying wards.'),
('Kochi','hi','तटीय तूफानी लहरों और वेम्बनाड बैकवाटर के अतिप्रवाह से इस क्षेत्र में मध्यम बाढ़ जोखिम है। ज्वारीय प्रवेश और मानसूनी वर्षा मिलकर निचले वार्डों में जलभराव पैदा करते हैं।'),
('Kochi','bn','উপকূলীয় জলোচ্ছ্বাস ও ভেম্বানাড ব্যাকওয়াটারের উপচে পড়া জলে এখানে মাঝারি বন্যার ঝুঁকি রয়েছে। জোয়ারের জল ও বর্ষার বৃষ্টি একসঙ্গে নিচু ওয়ার্ডগুলিতে জলাবদ্ধতা সৃষ্টি করে।'),
('Kochi','gu','દરિયાઈ તોફાની મોજાં અને વેમ્બનાડ બેકવોટરના ઓવરફ્લોથી અહીં મધ્યમ પૂરનું જોખમ છે. ભરતીનું પાણી અને ચોમાસુ વરસાદ ભેગા થઈ નીચાણવાળા વોર્ડમાં પાણી ભરે છે.'),
('Kochi','kn','ಕರಾವಳಿ ಬಿರುಗಾಳಿ ಅಲೆ ಮತ್ತು ವೆಂಬನಾಡ್ ಹಿನ್ನೀರಿನ ಉಕ್ಕುವಿಕೆಯಿಂದ ಇಲ್ಲಿ ಮಧ್ಯಮ ಪ್ರವಾಹ ಅಪಾಯವಿದೆ. ಉಬ್ಬರದ ನೀರು ಮತ್ತು ಮಳೆಗಾಲದ ಮಳೆ ಸೇರಿ ತಗ್ಗು ವಾರ್ಡ್‌ಗಳಲ್ಲಿ ನೀರು ನಿಲ್ಲುತ್ತದೆ.'),
('Kochi','ml','തീരദേശ കൊടുങ്കാറ്റ് തിരയും വേമ്പനാട് കായലിലെ ജലം കവിഞ്ഞൊഴുകുന്നതും മൂലം ഇവിടെ ഇടത്തരം വെള്ളപ്പൊക്ക സാധ്യതയുണ്ട്. വേലിയേറ്റവും മൺസൂൺ മഴയും ചേർന്ന് താഴ്ന്ന വാർഡുകളിൽ വെള്ളക്കെട്ട് ഉണ്ടാക്കുന്നു.'),
('Kochi','mr','किनारी वादळी लाटा आणि वेम्बनाड बॅकवॉटरच्या ओसंडण्यामुळे येथे मध्यम स्वरूपाचा पूरधोका आहे. भरतीचे पाणी आणि पावसाळी पाऊस एकत्र आल्याने सखल प्रभागांत पाणी साचते.'),
('Kochi','pa','ਸਮੁੰਦਰੀ ਤੂਫ਼ਾਨੀ ਲਹਿਰਾਂ ਅਤੇ ਵੇਮਬਨਾਡ ਬੈਕਵਾਟਰ ਦੇ ਉਛਾਲ ਕਾਰਨ ਇੱਥੇ ਦਰਮਿਆਨਾ ਹੜ੍ਹ ਖ਼ਤਰਾ ਹੈ। ਜਵਾਰ ਦਾ ਪਾਣੀ ਅਤੇ ਮਾਨਸੂਨੀ ਮੀਂਹ ਮਿਲ ਕੇ ਨੀਵੇਂ ਵਾਰਡਾਂ ਵਿੱਚ ਪਾਣੀ ਭਰ ਦਿੰਦੇ ਹਨ।'),
('Kochi','ta','கடலோர புயல் அலைகள் மற்றும் வேம்பநாடு பின்னீர் நிரம்பி வழிவதால் இங்கு நடுத்தர வெள்ள அபாயம் உள்ளது. அலை நீர் மற்றும் பருவமழை சேர்ந்து தாழ்வான வார்டுகளில் நீர் தேங்குகிறது.'),
('Kochi','te','తీర తుఫాను అలలు, వేంబనాడ్ బ్యాక్‌వాటర్ పొంగడం వల్ల ఇక్కడ మధ్యస్థ వరద ముప్పు ఉంది. పోటు నీరు, రుతుపవన వర్షం కలిసి లోతట్టు వార్డుల్లో నీరు నిలిచేలా చేస్తాయి.'),
('Kochi','or','ଉପକୂଳ ଝଡ଼ ଢେଉ ଏବଂ ଭେମ୍ବନାଡ଼ ପଛଜଳ ଉଚ୍ଛୁଳିବା କାରଣରୁ ଏଠାରେ ମଧ୍ୟମ ବନ୍ୟା ବିପଦ ରହିଛି। ଜୁଆର ଜଳ ଓ ମୌସୁମୀ ବର୍ଷା ମିଶି ନିମ୍ନାଞ୍ଚଳ ୱାର୍ଡଗୁଡ଼ିକରେ ଜଳ ଜମାଏ।'),
('Kochi','ur','ساحلی طوفانی لہروں اور ویمبناڈ بیک واٹر کے بہاؤ سے یہاں درمیانے درجے کا سیلابی خطرہ ہے۔ مدوجزر کا پانی اور مون سون بارش مل کر نشیبی وارڈوں میں پانی جمع کر دیتے ہیں۔')
) AS v(city, lang, txt) ON v.city = z.city_name;
